      <div class="slot" data-t="11:00"><span>11:00</span><span class="am">ص</span></div>
      <div class="slot" data-t="11:30"><span>11:30</span><span class="am">ص</span></div>
      <div class="slot" data-t="12:00"><span>12:00</span><span class="am">ص</span></div>
    </div>
