</div>

<script>
(function(){
  const months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
  let year=2026, month=5; // يونيو 2026
  const today = new Date(2026,5,15); // اليوم المُشار إليه
  let selectedDate = new Date(today);

  const cal = document.getElementById('cal');
  const monthName = document.getElementById('monthName');

  function render(){
    const first = new Date(year,month,1);
    const daysInMonth = new Date(year,month+1,0).getDate();
    const startWeekday = first.getDay(); // 0 الأحد .. 6 السبت
    //}->{ week starts Saturday: Sat=0,Sun=1,Mon=2,Tue=3,Wed=4,Thu=5,Fri=6
    const leading = (startWeekday+1)%7;
    const prevDays = new Date(year,month,0).getDate();
    const total = leading + daysInMonth;
    const trailing = (7 - (total%7))%7;

    let html='';
    for(let i=0;i<leading;i++){
      const d = prevDays - leading + 1 + i;
      html += `<div class="cell other"><span class="d">${d}</span></div>`;
    }
    for(let d=1;d<=daysInMonth;d++){
      const date = new Date(year,month,d);
      let cls='cell';
      const isToday = date.getFullYear()===today.getFullYear()&&date.getMonth()===today.getMonth()&&date.getDate()===today.getDate();
      const isSel = date.getFullYear()===selectedDate.getFullYear()&&date.getMonth()===selectedDate.getMonth()&&date.getDate()===selectedDate.getDate();
      if(isToday) cls+=' today';
      if(isSel) cls+=' selected';
      html += `<div class="${cls}" data-day="${d}"><span class="d">${d}</span>${isToday?'<span class="dot"></span>':''}</div>`;
    }
    for(let i=0;i<trailing;i++){
      html += `<div class="cell other"><span class="d">${i+1}</span></div>`;
    }
    cal.innerHTML = html;
    monthName.textContent = `${months[month]} ${year}`;

    cal.querySelectorAll('.cell:not(.other)').forEach(el=>{
      el.addEventListener('click', ()=>{
        cal.querySelectorAll('.cell').forEach(c=>c.classList.remove('selected'));
        el.classList.add('selected');
        selectedDate = new Date(year,month,+el.dataset.day);
      });
    });
  }

  document.getElementById('prev').addEventListener('click', ()=>{
    month--; if(month<0){month=11;year--;} render();
  });
  document.getElementById('next').addEventListener('click', ()=>{
    month++; if(month>11){month=0;year++;} render();
  });

  let selectedSlot = null;
  document.querySelectorAll('.slot').forEach(s=>{
    s.addEventListener('click', ()=>{
      document.querySelectorAll('.slot').forEach(x=>x.classList.remove('selected'));
      s.classList.add('selected');
      selectedSlot = s.dataset.t;
    });
  });

  document.getElementById('confirm').addEventListener('click', ()=>{
    if(!selectedSlot){ alert('اختر الوقت'); return; }
    alert(`تم حجز الموعد في ${selectedDate.getDate()} ${months[month]} ${year} الساعة ${selectedSlot}`);
  });

  render();
})();
</script>
